import React, { useEffect, useRef, useState, useCallback } from "react";
import Chart from "chart.js/auto";

const DATA_PATH = "/smogon_csv/";

export default function ComUsage() {
  const chartRef = useRef(null);
  const canvasRef = useRef(null);

  const [files, setFiles] = useState([]);
  const [pokemonList, setPokemonList] = useState([]);
  const [selectedPokemon, setSelectedPokemon] = useState("");
  const [selectedGen, setSelectedGen] = useState("9");
  const [menuOpen, setMenuOpen] = useState(false);

  // 📂 Load file list (manual for now)
  useEffect(() => {
    const sampleFiles = [
      "2024-01_gen9doublesou-0.csv",
      "2024-02_gen9doublesou-0.csv",
      "2024-03_gen9doublesou-0.csv"
    ];
    setFiles(sampleFiles);
  }, []);

  const loadCSV = async (file) => {
    const res = await fetch(DATA_PATH + file);
    return await res.text();
  };

  const parseCSV = (text) =>
    text.split("\n").slice(1).map(r => r.split(","));

  // 🔥 Build Pokémon list (from all files)
  useEffect(() => {
    const buildPokemonList = async () => {
      const set = new Set();

      for (let file of files) {
        const text = await loadCSV(file);
        const rows = parseCSV(text);

        rows.forEach(row => {
          if (row[1]) set.add(row[1]);
        });
      }

      const list = Array.from(set).sort();
      setPokemonList(list);
      setSelectedPokemon(list[0]); // default
    };

    if (files.length) buildPokemonList();
  }, [files]);

  // 📈 Track usage over time
  const getUsageData = useCallback(async () => {
    const labels = [];
    const data = [];

    const sortedFiles = [...files].sort(); // chronological

    for (let file of sortedFiles) {
      if (!file.includes(`gen${selectedGen}`)) continue;

      const text = await loadCSV(file);
      const rows = parseCSV(text);

      const match = rows.find(r => r[1] === selectedPokemon);

      if (match) {
        labels.push(file.split("_")[0]);
        data.push(parseFloat(match[2]));
      }
    }

    return { labels, data };
  }, [files, selectedGen, selectedPokemon]);

  useEffect(() => {
    const buildChart = async () => {
      if (!selectedPokemon) return;

      const { labels, data } = await getUsageData();

      if (chartRef.current) chartRef.current.destroy();

      chartRef.current = new Chart(canvasRef.current, {
        type: "line",
        data: {
          labels,
          datasets: [
            {
              label: `${selectedPokemon} Usage (%)`,
              data,
              tension: 0.3
            }
          ]
        }
      });
    };

    buildChart();
  }, [getUsageData, selectedPokemon]);

  return (
    <div>
      <h2>Pokémon Usage Over Time</h2>

      {/* 🍔 MENU */}
      <div style={{ position: "absolute", top: 20, right: 20 }}>
        <button onClick={() => setMenuOpen(!menuOpen)}>☰</button>
      </div>

      {menuOpen && (
        <div style={{
          position: "absolute",
          top: 60,
          right: 20,
          background: "#eee",
          padding: "15px",
          borderRadius: "8px",
          maxHeight: "400px",
          overflowY: "scroll"
        }}>
          <h4>Filters</h4>

          {/* Generation */}
          <label>Generation:</label>
          <select
            value={selectedGen}
            onChange={(e) => setSelectedGen(e.target.value)}
          >
            {[6,7,8,9].map(g => (
              <option key={g} value={g}>Gen {g}</option>
            ))}
          </select>

          <br /><br />

          {/* Pokémon selector */}
          <label>Pokémon:</label>
          <select
            value={selectedPokemon}
            onChange={(e) => setSelectedPokemon(e.target.value)}
          >
            {pokemonList.map(p => (
              <option key={p} value={p}>{p}</option>
            ))}
          </select>
        </div>
      )}

      <canvas ref={canvasRef}></canvas>
    </div>
  );
}
